import sys,json
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]/'backend'))
from app.models.schemas import LLMTriageExtraction,RequiredDocumentItem
root=Path(__file__).resolve().parents[1]
cases=[
 dict(id='gst-asmt-10',code='GST',title='Input tax credit mismatch',authority='Office of the Superintendent, CGST Range-III, Mumbai',law='Section 61 · CGST Act, 2017 · Rule 99(1)',form='GST ASMT-10',amount=142850,issue='2026-10-14',service='2026-10-15',window=15,email='superintendent.cgst@cbic.gov.in',din='CBIC-20261067B892104432',summary='Your GSTR-3B claims ₹1,42,850 more input tax credit than your GSTR-2B shows. Two suppliers — Apex Fasteners and Surya Packaging — filed their returns late. Reconcile the invoices and explain the difference to the GST officer.',hindi='आपके GSTR-3B में GSTR-2B से ₹1,42,850 अधिक इनपुट टैक्स क्रेडिट है। दो आपूर्तिकर्ताओं ने रिटर्न देर से भरा है। बिलों का मिलान करके GST अधिकारी को अंतर का जवाब दें।',professional='Chartered Accountant',reason='Reconcile the credit difference with your CA before filing a response.',docs=[('Invoice-wise ITC reconciliation','Explains the difference between GSTR-2B and GSTR-3B.','GST portal → Returns → GSTR-2B; reconcile with your books.'),('Supplier invoices & e-Way bills','Supports the purchases from Apex Fasteners and Surya Packaging.','Purchase register → supplier invoices for FY 2025–26, Q2.'),('Proof of supplier payments','Documents the dates and amounts paid to the suppliers.','Your bank → Account statement → relevant transactions.')]),
 dict(id='cheque-section-138',code='LEGAL',title='Cheque dishonour demand',authority='Chambers of Adv. Rajeshwar Rao, Mumbai',law='Section 138 · Negotiable Instruments Act, 1881',form='LEGAL DEMAND',amount=480000,issue='2026-10-10',service='2026-10-12',window=15,email='rao.legal.chambers@gmail.com',din=None,summary='Cheque 048921 for ₹4,80,000 was returned for insufficient funds. The sender demands payment within 15 days of receipt. Take the notice and bank memo to an advocate promptly to assess payment or a response.',hindi='₹4,80,000 का चेक 048921 अपर्याप्त राशि के कारण लौट गया। प्राप्ति के 15 दिनों के भीतर भुगतान की मांग है। नोटिस और बैंक मेमो लेकर तुरंत वकील से सलाह लें।',professional='Advocate',reason='A dishonoured cheque demand can involve criminal proceedings. Obtain advocate review promptly.',criminal=True,docs=[('Notice & postal delivery record','Establishes the exact receipt date and demand.','Registered post envelope, tracking receipt and original notice.'),('Cheque copy & bank return memo','Records the instrument and stated reason for dishonour.','Bank branch → Cheque return memo.'),('Contract & payment correspondence','Helps the advocate assess the underlying liability.','Purchase agreement, invoices and correspondence.')]),
 dict(id='gst-quishing',code='FRAUD',title='GST suspension payment scam',authority='“GSTN Compliance & Enforcement Cell”',law='Claimed Form GST REG-17',form='REG-17 SPOOF',amount=14999,issue='2026-10-23',service='2026-10-24',window=1,email='compliance-alert@gst-portal-verify.in',din=None,summary='Pay ₹14,999 via QR code within 4 hours or GSTIN and bank account will be frozen immediately. upi://pay?pa=gst.penalty.desk@okicici&am=14999',hindi='',professional='Do not engage',reason='',docs=[]),
 dict(id='income-tax-143',code='IT',title='Income tax return intimation',authority='Centralized Processing Centre, Income Tax Department',law='Section 143(1) · Income Tax Act, 1961',form='ITR INTIMATION',amount=1840,issue='2026-10-03',service='2026-10-04',window=30,email='intimations@cpc.incometax.gov.in',din='ITBA/AST/S/143(1)/2026-27/1089432119(1)',summary='Your ITR-3 for AY 2026–27 has been processed. An interest recalculation shows a difference of ₹1,840. Compare the computation with your return and confirm any outstanding demand directly on the official portal before acting.',hindi='AY 2026–27 का आपका ITR-3 प्रोसेस हो गया है। ब्याज की पुनर्गणना से ₹1,840 का अंतर है। अपने रिटर्न से गणना मिलाएँ और कार्रवाई से पहले आधिकारिक पोर्टल पर मांग की जाँच करें।',professional='Owner review',reason='Start by comparing the computation with the filed return; seek a CA if you disagree.',docs=[('Filed ITR & computation','Allows comparison with the processing intimation.','Income tax portal → Filed returns → AY 2026–27.'),('Tax payment challans','Verifies credit for amounts already paid.','Income tax portal → Payment history.')]),
 dict(id='epfo-14b',code='EPFO',title='Delayed PF remittance',authority='Regional Provident Fund Commissioner-II, Pune',law='Sections 14B & 7Q · EPF & MP Act, 1952',form='SHOW-CAUSE',amount=52600,issue='2026-10-17',service='2026-10-17',window=15,email='ro.pune@epfindia.gov.in',din=None,summary='EPFO proposes ₹38,400 in damages and ₹14,200 in interest for late PF contributions between April and July 2026. Gather the ECRs and payment records, then prepare a representation with your advisor.',hindi='अप्रैल से जुलाई 2026 के PF भुगतान में देरी पर EPFO ने ₹38,400 हर्जाना और ₹14,200 ब्याज प्रस्तावित किया है। ECR और भुगतान रिकॉर्ड इकट्ठा करके सलाहकार के साथ जवाब तैयार करें।',professional='Chartered Accountant',reason='Check the month-wise calculation and grounds for a representation with a professional.',rollover=True,docs=[('ECR statements: April–July 2026','Identifies the contribution periods under review.','EPFO employer portal → ECR / Returns.'),('PF challans & payment receipts','Establishes the actual remittance dates.','EPFO employer portal → Payments → Challan history.'),('Month-wise delay explanation','Supports your representation on the proposed damages.','Payroll records and supporting correspondence.')]),
]
playbooks=[]
fixtures=[]
for c in cases:
 raw=f"{c['authority']}\n{c['form']}\n{c['law']}\nDate of issue: {c['issue']}\nResponse within {c['window']} days\nTotal demand: INR {c['amount']}\n"+(f"DIN: {c['din']}\n" if c['din'] else '')+c['summary']+'\nPAN: ABCDE1234F\nAadhaar: 2345 6789 0123'
 (root/'backend/app/data/demo_notices'/f"{c['id']}.txt").write_text(raw)
 fixtures.append({**c,'raw_text':raw})
 if c['id']=='gst-quishing': continue
 docs=[RequiredDocumentItem(doc_id=f'doc-{i+1}',document_name=d[0],why_needed=d[1],source_hint=d[2]) for i,d in enumerate(c['docs'])]
 draft=f"To,\n{c['authority']}\n\nSubject: Response to {c['form']}\nReference: [NOTICE_REFERENCE]\n\nRespected Sir / Madam,\n\nWe acknowledge receipt of the above communication on [DATE_OF_RECEIPT]. We submit the following for your consideration, subject to verification of the records.\n\n1. [FACTUAL_EXPLANATION_WITHOUT_UNVERIFIED_ADMISSIONS]\n2. [RECONCILIATION_OR_PAYMENT_DETAILS]\n3. Supporting records are indexed in the attached evidence list.\n\nWe request that the enclosed records be considered and an opportunity to clarify any remaining issues be provided.\n\nYours faithfully,\n[AUTHORIZED_SIGNATORY]\n[BUSINESS_NAME]\n[DATE]\n\nDRAFT FOR PROFESSIONAL REVIEW — verify all facts before signing or submission."
 triage=LLMTriageExtraction(issuing_authority=c['authority'],notice_type_title=c['title'],statutory_act_and_section=c['law'],plain_english_summary=c['summary'],core_allegation_or_query=c['summary'],financial_demand_inr=c['amount'],date_of_issue_iso=c['issue'],response_window_days=c['window'],has_criminal_or_arrest_clause=c.get('criminal',False),recommended_professional=c['professional'],professional_reason=c['reason'],required_documents=docs,draft_reply_template=draft,vernacular_summary_hindi=c['hindi'])
 playbooks.append({'id':c['id'],'form':c['form'],'triage':triage.model_dump()})
(root/'backend/app/data/statutory_playbooks.json').write_text(json.dumps(playbooks,ensure_ascii=False,indent=2))
(root/'backend/app/data/demo_cases.json').write_text(json.dumps(fixtures,ensure_ascii=False,indent=2))
